import { Test } from '@nestjs/testing';
import { INestApplication } from '@nestjs/common';
import * as request from 'supertest';
import { DataSource } from 'typeorm';
import { AppModule } from '../src/app.module';

describe('Orders API (e2e)', () => {
  let app: INestApplication;
  let dataSource: DataSource;

  // Runs before EVERY single test — both the app boot and the full data
  // wipe/reseed happen here, N times for N tests.
  beforeEach(async () => {
    // 1) App bootstrap: recompiles the whole DI container and re-opens the
    // ORM connection from scratch, every single test.
    const moduleRef = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();

    app = moduleRef.createNestApplication();
    await app.init();
    dataSource = app.get(DataSource);

    // 2) Over-broad cleanup: wipe EVERY table (mutated ones AND reference
    // tables), then immediately re-seed the reference/master data — before
    // every single test, even though tests never write to these tables.
    const entityMetadatas = dataSource.entityMetadatas;
    for (const metadata of entityMetadatas) {
      const repository = dataSource.getRepository(metadata.name);
      await repository.query(`TRUNCATE TABLE "${metadata.tableName}" CASCADE`);
    }

    await dataSource.query(`
      INSERT INTO categories (id, name) VALUES
        (1, 'Electronics'),
        (2, 'Books'),
        (3, 'Groceries');
    `);
    await dataSource.query(`
      INSERT INTO roles (id, name) VALUES
        (1, 'admin'),
        (2, 'customer');
    `);
    await dataSource.query(`
      INSERT INTO products (id, name, category_id, price) VALUES
        (1, 'Wireless Mouse', 1, 25.99),
        (2, 'Mechanical Keyboard', 1, 89.99),
        (3, 'Clean Code', 2, 34.50),
        (4, 'Organic Coffee Beans', 3, 12.75);
    `);
  });

  afterEach(async () => {
    await app.close();
  });

  it('creates a new order and returns 201', async () => {
    const payload = { productId: 1, quantity: 2 };

    await request(app.getHttpServer())
      .post('/orders')
      .send(payload)
      .expect(201);
  });

  it('lists all orders and returns 200', async () => {
    await request(app.getHttpServer())
      .get('/orders')
      .expect(200);
  });

  it('creates an order with multiple items and returns 201', async () => {
    const payload = {
      items: [
        { productId: 2, quantity: 1 },
        { productId: 3, quantity: 3 },
      ],
    };

    await request(app.getHttpServer())
      .post('/orders')
      .send(payload)
      .expect(201);
  });

  it('rejects an order for an unknown product with 400', async () => {
    const payload = { productId: 9999, quantity: 1 };

    await request(app.getHttpServer())
      .post('/orders')
      .send(payload)
      .expect(400);
  });

  // ...roughly 26 more tests in this file, each following the same shape:
  // one or two calls into /orders that only ever touch the `orders` and
  // `order_items` tables, never `categories` / `roles` / `products`.
});
